		animation-timing-function: steps(1, end);
		animation-iteration-count: infinite;
		animation-play-state: paused;
	}

	.from {
		animation-name: forest-hop-out;
	}

	.to {
		animation-name: forest-hop-in;
	}

	.from-0,
	.to-0 {
